#include "core.hpp"
#include <iostream>
#include <stdexcept>
int main(int argc,char** argv){try{std::string name="default",config,output="output",saved,seed;bool has_seed=false;
for(int i=1;i<argc;++i){std::string a=argv[i];if(a=="--help"){std::cout<<"portfolio [--profile default|short|long|floating] [--config file.ini] [--seed N] [--out EMPTY_DIR] [--save-config file.ini]\n";return 0;}if(i+1>=argc)throw std::runtime_error("Missing value");std::string v=argv[++i];if(a=="--profile")name=v;else if(a=="--config")config=v;else if(a=="--out")output=v;else if(a=="--save-config")saved=v;else if(a=="--seed"){seed=v;has_seed=true;}else throw std::runtime_error("Unknown option");}
if(name!="default"&&!config.empty())throw std::runtime_error("Choose profile OR config");auto c=config.empty()?pg::profile(name):pg::load(std::filesystem::u8path(config));if(has_seed){std::size_t used=0;auto n=std::stoll(seed,&used);if(used!=seed.size()||n<0||n>4294967295LL)throw std::runtime_error("Invalid seed");c.seed=static_cast<unsigned>(n);}pg::validate(c);if(!saved.empty()){auto p=std::filesystem::u8path(saved);if(std::filesystem::exists(p))throw std::runtime_error("Config already exists");pg::save(c,p);}auto d=pg::generate(c);pg::report(c,d,std::filesystem::u8path(output));std::cout<<pg::summary(c,d)<<"Report: "<<output<<"/report.html\n";return 0;}catch(const std::exception& e){std::cerr<<"Error: "<<e.what()<<'\n';return 1;}}
